export type Card = {
  monster: string;
  rank?: number;
};

const NO_SPHINX_SCORE = 0;

/**
 * Every army seen so far that contains a Sphinx scores 2. The tests do not yet
 * distinguish the parts of that number, so it stays a single constant.
 */
const SPHINX_ARMY_SCORE = 2;

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

export const scoreArmy = (army: Card[]): number =>
  army.some(isSphinx) ? SPHINX_ARMY_SCORE : NO_SPHINX_SCORE;

